<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { getList, getPage, post, put } from '@/api/resources'
import { http, problemMessage } from '@/api/http'
import { useSessionStore } from '@/stores/session'
import type { Alert, Device, Metric } from '@/types/domain'
import MetricChart from '@/components/MetricChart.vue'
import ProductionHint from '@/components/ProductionHint.vue'
import SourceBadge from '@/components/SourceBadge.vue'
import StatusTag from '@/components/StatusTag.vue'
import { formatDate, formatNumber } from '@/utils/format'

interface Rule { id: string; deviceId?: string; deviceType?: string; metricCode: string; unit: string; lower?: number; upper?: number; recoveryLower?: number; recoveryUpper?: number; severity: string; enabled: boolean; version?: number }
interface MetricDefinition { code: string; name: string; unit: string; deviceType: string }
interface Pest { id: string; species?: string; deviceId?: string; count: number; observedAt?: string; notes?: string }
const tab = ref('monitor'); const devices = ref<Device[]>([]); const latest = ref<Metric[]>([]); const definitions = ref<MetricDefinition[]>([]); const alerts = ref<Alert[]>([]); const rules = ref<Rule[]>([]); const pests = ref<Pest[]>([]); const trends = ref<{ time: string; value: number }[]>([]); const simulation = ref(false); const loading = ref(true); const error = ref(''); const deviceType = ref(''); const selectedDevice = ref(''); const manual = reactive({ deviceId: '', metricCode: 'soilMoisture', value: 0, unit: '%' }); const rule = reactive<Partial<Rule>>({ metricCode: 'soilMoisture', unit: '%', severity: 'Warning', enabled: true }); const pest = reactive({ count: 0, species: '', notes: '' }); const visitorCount = reactive({ direction: 'In', count: 1 }); let timer: number | undefined
const session = useSessionStore()
const metricName = (code: string): string => definitions.value.find((item) => item.code === code)?.name ?? code
const activeMetric = computed(() => latest.value.find((item) => item.deviceId === selectedDevice.value) ?? latest.value[0])
async function load(): Promise<void> { loading.value = !devices.value.length; error.value = ''; try { const [d, m, definitionsData, a, r, p, s] = await Promise.all([getList<Device>('/iot/devices', deviceType.value ? { type: deviceType.value } : undefined), getList<Metric>('/iot/latest'), getPage<MetricDefinition>('/iot/metrics', { pageSize: 100 }), getPage<Alert>('/iot/alerts'), getList<Rule>('/iot/rules'), getList<Pest>('/iot/pests'), http.get<{ enabled: boolean }>('/iot/simulation')]); devices.value = d; latest.value = m; definitions.value = definitionsData.items; alerts.value = a.items; rules.value = r; pests.value = p; simulation.value = s.data.enabled; if (!selectedDevice.value && d[0]) selectedDevice.value = d[0].id; if (!manual.deviceId && d[0]) manual.deviceId = d[0].id; await loadTrend() } catch (e) { error.value = problemMessage(e) } finally { loading.value = false } }
async function loadTrend(): Promise<void> { const metric = activeMetric.value; if (!metric?.deviceId) { trends.value = []; return } try { trends.value = (await getList<{ time: string; value: number }>('/iot/trends', { deviceId: metric.deviceId, metricCode: metric.metricCode, hours: 24 })) } catch { trends.value = [] } }
async function toggleSimulation(): Promise<void> { try { await post('/iot/simulation', { enabled: !simulation.value }); simulation.value = !simulation.value; ElMessage.success(simulation.value ? '内部模拟器已显式开启。' : '内部模拟器已停止。') } catch (e) { ElMessage.error(problemMessage(e)) } }
async function ingest(): Promise<void> { if (!manual.deviceId || !manual.metricCode || !manual.unit) return ElMessage.warning('请完整填写人工录入数据。'); try { await post('/iot/telemetry', { ...manual, collectedAt: new Date().toISOString(), idempotencyKey: crypto.randomUUID() }); ElMessage.success('人工遥测已录入。'); await load() } catch (e) { ElMessage.error(problemMessage(e)) } }
async function recordVisitorCount(): Promise<void> { if (!Number.isInteger(visitorCount.count) || visitorCount.count < 1 || visitorCount.count > 10_000) return ElMessage.warning('进出人数需为 1 至 10000 的整数。'); try { await post('/iot/visitor-counts', { ...visitorCount, collectedAt: new Date().toISOString(), idempotencyKey: crypto.randomUUID() }); ElMessage.success('人工游客计数已录入。'); visitorCount.count = 1 } catch (e) { ElMessage.error(problemMessage(e)) } }
async function scenario(kind: 'Abnormal' | 'Recovery'): Promise<void> { if (!selectedDevice.value || !activeMetric.value) return; try { await post('/iot/scenarios', { deviceId: selectedDevice.value, metricCode: activeMetric.value.metricCode, scenario: kind }); ElMessage.success(kind === 'Abnormal' ? '异常模拟已请求。' : '恢复模拟已请求。'); await load() } catch (e) { ElMessage.error(problemMessage(e)) } }
async function acknowledge(item: Alert): Promise<void> { try { await post(`/iot/alerts/${item.id}/acknowledge`); await load(); ElMessage.success('告警已确认，确认不等于恢复。') } catch (e) { ElMessage.error(problemMessage(e)) } }
async function saveRule(): Promise<void> { if (!rule.metricCode || !rule.unit) return ElMessage.warning('请填写指标和单位。'); try { if (rule.id) await put(`/iot/rules/${rule.id}`, rule); else await post('/iot/rules', rule); Object.assign(rule, { id: undefined, deviceId: undefined, deviceType: undefined, metricCode: 'soilMoisture', unit: '%', lower: undefined, upper: undefined, recoveryLower: undefined, recoveryUpper: undefined, severity: 'Warning', enabled: true }); await load(); ElMessage.success('阈值规则已保存。') } catch (e) { ElMessage.error(problemMessage(e)) } }
async function addPest(): Promise<void> { if (!pest.species || pest.count < 0) return ElMessage.warning('请填写位置与有效虫数。'); try { await post('/iot/pests', pest); Object.assign(pest, { count: 0, species: '', notes: '' }); await load(); ElMessage.success('虫情人工记录已新增。') } catch (e) { ElMessage.error(problemMessage(e)) } }
function editRule(item: Rule): void { Object.assign(rule, item) }
onMounted(() => { void load(); timer = window.setInterval(() => { if (!document.hidden && tab.value === 'monitor') void load() }, 10_000) }); onBeforeUnmount(() => window.clearInterval(timer))
</script>
<template><div class="page"><div class="page-heading"><div><h1>智能物联</h1><p>统一查看台账、指标、规则、告警与内部模拟。页面每 10 秒刷新，隐藏时暂停。</p></div><div><el-tag :type="simulation ? 'warning' : 'info'">{{ simulation ? '模拟器已开启' : '模拟器关闭' }}</el-tag><el-button v-if="session.hasAnyRole(['Administrator'])" class="sim-button" :type="simulation ? 'warning' : 'primary'" @click="toggleSimulation">{{ simulation ? '停止模拟器' : '启动模拟器' }}</el-button></div></div><el-alert v-if="error" type="error" :title="error" :closable="false" /><el-tabs v-model="tab"><el-tab-pane label="监测台账" name="monitor"><div class="iot-toolbar"><el-select v-model="deviceType" aria-label="按设备类型筛选" clearable placeholder="按设备类型筛选" @change="load"><el-option v-for="type in ['Soil','WaterLevel','WaterQuality','Toilet','Noise','Weather','Pest','Camera','Irrigation','Lamp','Broadcast']" :key="type" :value="type" :label="type" /></el-select><el-select v-model="selectedDevice" aria-label="选择设备" placeholder="选择设备" @change="loadTrend"><el-option v-for="item in devices" :key="item.id" :value="item.id" :label="`${item.code} · ${item.type}`" /></el-select></div><div class="grid-2"><section class="surface latest-panel" v-loading="loading"><div class="data-title">最新指标</div><div class="metric-cards"><article v-for="metric in latest" :key="`${metric.deviceId}-${metric.metricCode}`" :class="{ stale: metric.stale }"><span>{{ metricName(metric.metricCode) }}</span><b>{{ formatNumber(metric.value, 2) }} <small>{{ metric.unit }}</small></b><div><SourceBadge :source="metric.source" /><small>{{ formatDate(metric.collectedAt) }}{{ metric.stale ? ' · 已过期' : '' }}</small></div></article><el-empty v-if="!latest.length && !loading" description="暂无指标" /></div></section><section class="surface trend-panel"><div class="data-title">设备趋势</div><MetricChart :points="trends" :unit="activeMetric?.unit" /></section></div><section class="surface manual-panel"><div><b>人工遥测录入</b><p>会标记为 Manual，并使用同一阈值与告警服务。</p></div><div class="inline-form"><el-select v-model="manual.deviceId" placeholder="设备"><el-option v-for="item in devices" :key="item.id" :value="item.id" :label="item.code" /></el-select><el-input v-model="manual.metricCode" placeholder="指标编码" /><el-input-number v-model="manual.value" /><el-input v-model="manual.unit" placeholder="单位" /><el-button type="primary" @click="ingest">人工录入</el-button></div></section><section class="surface manual-panel"><div><b>人工游客进出计数</b><p>会标记为 Manual；出园人数不得超过当前在园人数。</p></div><div class="inline-form"><el-select v-model="visitorCount.direction" aria-label="进出方向"><el-option label="入园" value="In" /><el-option label="出园" value="Out" /></el-select><el-input-number v-model="visitorCount.count" :min="1" :max="10000" :precision="0" aria-label="人数" /><el-button type="primary" @click="recordVisitorCount">录入游客计数</el-button></div></section><div class="scenario"><el-button :disabled="!selectedDevice" type="danger" plain @click="scenario('Abnormal')">触发异常模拟</el-button><el-button :disabled="!selectedDevice" type="success" plain @click="scenario('Recovery')">触发恢复模拟</el-button><span>场景只为管理员演示，仍走真实告警和事件业务规则。</span></div></el-tab-pane><el-tab-pane label="视频 / 广播 / 路灯" name="media"><section class="surface media-grid"><div><h3>视频资源台账</h3><p>摄像头仅作为示例资源登记，不播放实时流或检查在线状态。</p><el-table :data="devices.filter(item => item.type === 'Camera')" empty-text="暂无视频资源"><el-table-column prop="code" label="资源编码" /><el-table-column prop="model" label="说明" /></el-table></div><div><h3>广播与路灯控制</h3><p>请前往智能控制提交带“模拟”标识的指令；浏览器音频只可显式预听。</p><el-button type="primary" @click="$router.push('/admin/control')">前往模拟控制</el-button></div></section><ProductionHint topic="video" /><ProductionHint topic="control" compact /></el-tab-pane><el-tab-pane label="虫情记录" name="pests"><div class="grid-2"><section class="surface table-panel"><el-table :data="pests" empty-text="暂无虫情记录"><el-table-column prop="species" label="虫种" /><el-table-column prop="count" label="虫数" /><el-table-column prop="notes" label="说明" /><el-table-column label="观测时间"><template #default="scope">{{ formatDate(scope.row.observedAt) }}</template></el-table-column></el-table></section><section class="surface rule-form"><div class="data-title">人工虫情记录</div><el-form label-position="top"><el-form-item label="虫种"><el-input v-model="pest.species" /></el-form-item><el-form-item label="虫数"><el-input-number v-model="pest.count" :min="0" /></el-form-item><el-form-item label="说明"><el-input v-model="pest.notes" type="textarea" /></el-form-item><el-button type="primary" @click="addPest">新增人工记录</el-button></el-form></section></div></el-tab-pane><el-tab-pane label="阈值规则" name="rules"><div class="grid-2"><section class="surface table-panel"><el-table :data="rules" empty-text="暂无规则"><el-table-column prop="metricCode" label="指标" /><el-table-column prop="deviceType" label="设备类型" /><el-table-column label="范围" width="150"><template #default="scope">{{ scope.row.lower ?? '—' }} ~ {{ scope.row.upper ?? '—' }} {{ scope.row.unit }}</template></el-table-column><el-table-column prop="severity" label="级别" /><el-table-column label="状态"><template #default="scope"><StatusTag :status="scope.row.enabled ? 'Enabled' : 'Disabled'" /></template></el-table-column><el-table-column label="操作"><template #default="scope"><el-button link type="primary" @click="editRule(scope.row)">编辑</el-button></template></el-table-column></el-table></section><section class="surface rule-form"><div class="data-title">{{ rule.id ? '编辑规则' : '新增规则' }}</div><el-form label-position="top"><div class="form-row"><el-form-item label="设备类型"><el-input v-model="rule.deviceType" placeholder="可为空" /></el-form-item><el-form-item label="指标编码"><el-input v-model="rule.metricCode" /></el-form-item></div><div class="form-row"><el-form-item label="下限"><el-input-number v-model="rule.lower" /></el-form-item><el-form-item label="上限"><el-input-number v-model="rule.upper" /></el-form-item></div><div class="form-row"><el-form-item label="恢复下限"><el-input-number v-model="rule.recoveryLower" /></el-form-item><el-form-item label="恢复上限"><el-input-number v-model="rule.recoveryUpper" /></el-form-item></div><div class="form-row"><el-form-item label="单位"><el-input v-model="rule.unit" /></el-form-item><el-form-item label="级别"><el-select v-model="rule.severity"><el-option value="Warning" /><el-option value="Critical" /></el-select></el-form-item></div><el-checkbox v-model="rule.enabled">启用规则</el-checkbox><br><el-button type="primary" class="save-rule" @click="saveRule">保存阈值规则</el-button></el-form></section></div></el-tab-pane><el-tab-pane label="告警中心" name="alerts"><section class="surface table-panel"><el-table :data="alerts" empty-text="暂无告警"><el-table-column prop="metricCode" label="指标" /><el-table-column label="读数" width="150"><template #default="scope">{{ scope.row.value }} {{ scope.row.unit }}</template></el-table-column><el-table-column prop="severity" label="级别" /><el-table-column prop="status" label="状态" /><el-table-column label="时间" width="180"><template #default="scope">{{ formatDate(scope.row.createdAt) }}</template></el-table-column><el-table-column label="关联" width="160"><template #default="scope"><el-button v-if="scope.row.eventId" link type="primary" @click="$router.push(`/admin/emergency/${scope.row.eventId}`)">查看关联事件</el-button></template></el-table-column><el-table-column label="操作" width="110"><template #default="scope"><el-button link type="primary" :disabled="scope.row.status === 'Acknowledged'" @click="acknowledge(scope.row)">确认告警</el-button></template></el-table-column></el-table></section></el-tab-pane></el-tabs><ProductionHint topic="telemetry" /></div></template>
<style scoped>.sim-button { margin-left:10px; }.iot-toolbar,.inline-form { display:flex; flex-wrap:wrap; gap:10px; margin-bottom:16px; }.iot-toolbar .el-select { width:230px; }.latest-panel,.trend-panel,.table-panel,.rule-form { padding:18px; }.metric-cards { display:grid; grid-template-columns:1fr 1fr; gap:10px; margin-top:15px; }.metric-cards article { padding:12px; border:1px solid #e4ece8; border-radius:9px; }.metric-cards article.stale { opacity:.55; }.metric-cards span,.metric-cards small { display:block; color:#758680; font-size:11px; }.metric-cards b { display:block; margin:5px 0 9px; color:#24725f; font-size:20px; }.metric-cards b small { display:inline; font-size:11px; }.metric-cards article div { display:flex; align-items:center; justify-content:space-between; gap:5px; }.manual-panel { margin-top:18px; padding:16px; display:flex; align-items:center; justify-content:space-between; gap:20px; }.manual-panel p { margin:5px 0 0; color:#71827d; font-size:12px; }.inline-form { margin:0; }.inline-form .el-select,.inline-form .el-input,.inline-form .el-input-number { width:140px; }.scenario { margin-top:14px; display:flex; gap:10px; align-items:center; }.scenario span { color:#778983; font-size:12px; }.media-grid { display:grid; grid-template-columns:1.2fr .8fr; gap:18px; padding:20px; }.media-grid h3 { margin-top:0; color:#294d44; }.media-grid p { color:#6d7f79; line-height:1.7; font-size:13px; }.form-row { display:grid; grid-template-columns:1fr 1fr; gap:12px; }.save-rule { margin-top:14px; }</style>
